"""Bullet cues generated by Claude Code agents instead of the API (Kian, 2026-11-10).

    uv run --no-sync python scripts/bullet_cue_agents.py dump
    uv run --no-sync python scripts/bullet_cue_agents.py ingest --run <run_id>

``dump`` writes one job file per TEST unit to ``data/private/reader/cue_jobs/`` holding exactly
what the API condition sent (``prompts/bullet_cue.v2.md`` input: every notes bullet, then per
bullet its parents and its hand-aligned span widened by ``PAD`` lines). An agent answers each
bullet with one JSON line ``{"bullet_id": ..., "found": [...], "cues": [...]}`` in the
:class:`tenor.evals.bullet_cues.CueOut` shape. ``ingest`` validates those lines, checks every
quote against its span (``cue_rows``), and writes the condition-blind reader packets and the key
(``build_packets``) plus the local rows. Local data only: no LLM, no network.
"""

from __future__ import annotations

import argparse
import json
from datetime import UTC, datetime
from pathlib import Path
from typing import Any

from tenor.evals import bullet_cues as B
from tenor.evals import coverage_e4 as C4

READERS = Path("data/private/reader")
JOBS = READERS / "cue_jobs"
OUT = READERS / "cue_agent_runs"
MODEL = "agent"


def _setup() -> tuple[list[B.CueUnit], dict[str, Any]]:
    units = [u for u in B.load_units(READERS / "packets", C4.TEST_MEETINGS) if u.split == "test"]
    maps = B.load_maps(Path("data/private/feature_tests/map"))
    return units, maps


def dump() -> None:
    units, maps = _setup()
    JOBS.mkdir(parents=True, exist_ok=True)
    prompt = Path(f"prompts/{B.PROMPT}.md").read_text(encoding="utf-8")
    total = 0
    for u in units:
        jobs = B.jobs_for(u, maps[u.key]["bullet_map"])
        parts = [f"# Cue jobs: {u.key} ({len(jobs)} bullets)\n\n## Instructions\n\n{prompt}\n",
                 "## Notes (shared by every job)\n\n" + B.notes_block(u)]  # fmt: skip
        for j in jobs:
            parts.append(f"## Job {j.bullet_id}\n\n" + B.bullet_block(j))
        (JOBS / f"{u.meeting_id}__{u.product}.md").write_text("\n".join(parts), encoding="utf-8")
        total += len(jobs)
        print(f"{u.key}: {len(jobs)} jobs")
    print(f"{total} jobs in {JOBS}")


def ingest(run: str, seed: int) -> None:
    units, maps = _setup()
    rows: list[dict[str, Any]] = []
    errors: list[str] = []
    for u in units:
        path = OUT / run / f"{u.meeting_id}__{u.product}.jsonl"
        jobs = {j.bullet_id: j for j in B.jobs_for(u, maps[u.key]["bullet_map"])}
        seen: set[str] = set()
        if not path.exists():
            errors.append(f"{u.key}: no output")
            continue
        for n, ln in enumerate(path.read_text(encoding="utf-8").splitlines(), 1):
            if not ln.strip():
                continue
            try:
                d = json.loads(ln)
                bid = d.pop("bullet_id")
                out = B.CueOut.model_validate(d)
            except Exception as e:  # noqa: BLE001 - report every bad line, keep going
                errors.append(f"{u.key} line {n}: {e}")
                continue
            if bid not in jobs or bid in seen:
                errors.append(f"{u.key} line {n}: unknown or repeated bullet {bid}")
                continue
            seen.add(bid)
            rows.append({"unit": u.key, "bullet_id": bid, "model": MODEL,
                         "cues": B.cue_rows(jobs[bid], out)})  # fmt: skip
        if missing := sorted(set(jobs) - seen):
            errors.append(f"{u.key}: {len(missing)} bullets unanswered")
    texts, key_units = B.build_packets(units, rows, {}, seed)
    pdir = READERS / "cue_packets" / run
    pdir.mkdir(parents=True, exist_ok=True)
    for name, text in texts.items():
        (pdir / name).write_text(text, encoding="utf-8")
    kdir = READERS / "cue_keys"
    kdir.mkdir(parents=True, exist_ok=True)
    key = {"meta": {"key_version": B.KEY_VERSION, "packet_version": B.PACKET_VERSION,
                    "reader_prompt": B.READER_PROMPT, "seed": seed, "run_id": run,
                    "models": [MODEL], "prompt": B.PROMPT,
                    "date": datetime.now(UTC).isoformat(timespec="seconds")},
           "units": key_units}  # fmt: skip
    (kdir / f"{run}.key.json").write_text(json.dumps(key, indent=1, ensure_ascii=False) + "\n")
    (OUT / run / "rows.json").write_text(json.dumps(rows, indent=1, ensure_ascii=False) + "\n")
    ok = sum(1 for r in rows for c in r["cues"] if c["status"] == "ok")
    bad = sum(1 for r in rows for c in r["cues"] if c["status"] != "ok")
    print(f"{len(rows)} bullets, {ok} cues ok, {bad} failed checks; packets {pdir}")
    print(f"items to read: {sum(len(u['items']) for u in key_units.values())}")
    for e in errors:
        print("ERROR", e)


if __name__ == "__main__":
    ap = argparse.ArgumentParser()
    sub = ap.add_subparsers(dest="cmd", required=True)
    sub.add_parser("dump")
    ing = sub.add_parser("ingest")
    ing.add_argument("--run", required=True)
    ing.add_argument("--seed", type=int, default=42)
    a = ap.parse_args()
    dump() if a.cmd == "dump" else ingest(a.run, a.seed)
